def transform(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # Copy original non-zero  
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                continue

            if val < 3:
                # Value 1: 2x2 fill to lower-right, value 2: horizontal line
                if val == 1:
                    dist = max(0, r - 3)
                    if c + dist < cols:
                        for dr in range(2):
                            for dc in range(2):
                                nr, nc = r + dr, c + dist + dc
                                if nc < cols:
                                    result[nr][nc] = 5
                        result[r][c + dist] = val
                        result[r][c + dist + 1] = val if result[r][c + dist + 1] == 0 else result[r][c + dist + 1]
                else:
                    # Value 2: horizontal only
                    dist = max(0, r - 3)
                    for i in range(c - 1, c - dist, -1):
                        result[r][i] = 5
                    result[r][c - dist] = val if c - dist >= 0 else 0
            else:
                # val >= 3: horizontal only
                dist = max(0, r - 3)
                if val % 2 == 1:
                    for i in range(c + 1, c + dist):
                        result[r][i] = 5
                else:
                    for i in range(c - 1, c - dist, -1):
                        result[r][i] = 5

    return result

