import json

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                continue

            if val == 1:
                if c + 1 < cols and r + 1 < rows:
                    result[r][c] = 1
                    result[r][c + 1] = 1
                    result[r + 1][c] = 5
                    result[r + 1][c + 1] = 5
            elif val == 2:
                dist = max(0, r - 3)
                end_col = c - dist
                for i in range(c - 1, end_col, -1):
                    if i >= 0:
                        result[r][i] = 5
                if end_col >= 0:
                    result[r][end_col] = 2
            else:
                dist = max(0, r - 3)
                if val % 2 == 1:
                    end_col = min(c + dist, cols - 1)
                    for i in range(c + 1, end_col + 1):
                        if i < cols:
                            result[r][i] = 5
                    result[r][end_col] = val
                else:
                    end_col = max(c - dist, 0)
                    for i in range(end_col + 1, c):
                        if i >= 0:
                            result[r][i] = 5
                    result[r][end_col] = val

    return result

