# Let me trace through the transformation for the test input
def trace_transform(grid):
    print(f"Input grid shape: {len(grid)}x{len(grid[0])}")

    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # Step 1: Copy non-zero cells
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                result[r][c] = grid[r][c]

    print("\nStep 1 after copying non-zeros:")
    for row in result:
        print(" ".join(str(x) for x in row))

    # Step 2: Apply rules
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                continue

            if val == 1:
                if c + 1 < cols and r + 1 < rows:
                    result[r][c] = 1
                    result[r][c + 1] = 1
                    result[r + 1][c] = 5
                    result[r + 1][c + 1] = 5
                    print(f"\nColor 1 at ({r},{c}): expanding to ({r},{c}),({r},{c+1}),({r+1},{c}),({r+1},{c+1})")
            elif val == 2:
                dist = max(0, r - 3)
                end_col = c - dist
                for i in range(c - 1, end_col, -1):
                    if i >= 0:
                        result[r][i] = 5
                if end_col >= 0:
                    result[r][end_col] = 2
                    print(f"\nColor 2 at ({r},{c}): pushing left by {dist}, marking ({r},{end_col})")
            else:
                dist = max(0, r - 3)
                if val % 2 == 1:  # odd
                    end_col = min(c + dist, cols - 1)
                    for i in range(c + 1, end_col + 1):
                        if i < cols:
                            result[r][i] = 5
                    result[r][end_col] = val
                    print(f"\nColor {val} (odd) at ({r},{c}): pushing right by {dist}, marking ({r},{end_col})")
                else:  # even
                    end_col = max(c - dist, 0)
                    for i in range(end_col + 1, c):
                        if i >= 0:
                            result[r][i] = 5
                    result[r][end_col] = val
                    print(f"\nColor {val} (even) at ({r},{c}): pushing left by {dist}, marking ({r},{end_col})")

    print("\n=== Final Result ===")
    for row in result:
        print(" ".join(str(x) for x in row))

    return result

